package mathx

import "testing"

// Code under test (normally in another file in the same package).
func Abs(n int) int {
	if n < 0 {
		return -n
	}
	return n
}

func TestAbs(t *testing.T) {
	// Each row is one scenario; name makes failures self-describing.
	tests := []struct {
		name string
		in   int
		want int
	}{
		{name: "positive", in: 5, want: 5},
		{name: "negative", in: -5, want: 5},
		{name: "zero", in: 0, want: 0},
	}

	for _, tc := range tests {
		tc := tc // Go <1.22: copy loop var before t.Run closure captures it.
		t.Run(tc.name, func(t *testing.T) {
			got := Abs(tc.in)
			if got != tc.want {
				// Errorf records the failure but lets other subtests run.
				t.Errorf("Abs(%d) = %d, want %d", tc.in, got, tc.want)
			}
		})
	}
}

package svc

import (
	"errors"
	"net/http"
	"net/http/httptest"
	"strconv"
	"testing"
)

var errNegative = errors.New("negative not allowed")

func ParsePositive(s string) (int, error) {
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, err
	}
	if n < 0 {
		return 0, errNegative
	}
	return n, nil
}

// mustErr is a helper; t.Helper() makes failures point at the caller.
func mustErr(t *testing.T, got, want error) {
	t.Helper()
	if !errors.Is(got, want) {
		t.Fatalf("error = %v, want %v", got, want)
	}
}

func TestParsePositive(t *testing.T) {
	tests := []struct {
		name    string
		in      string
		want    int
		wantErr error
	}{
		{"valid", "42", 42, nil},
		{"negative", "-1", 0, errNegative},
		{"not a number", "abc", 0, strconv.ErrSyntax},
	}
	for _, tc := range tests {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			got, err := ParsePositive(tc.in)
			if tc.wantErr != nil {
				mustErr(t, err, tc.wantErr)
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got != tc.want {
				t.Errorf("got %d, want %d", got, tc.want)
			}
		})
	}
}

func handler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusTeapot)
	_, _ = w.Write([]byte("hi"))
}

func TestHandler(t *testing.T) {
	t.Cleanup(func() { /* close resources opened for this test */ })
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	rec := httptest.NewRecorder() // in-memory ResponseWriter
	handler(rec, req)
	if rec.Code != http.StatusTeapot {
		t.Errorf("status = %d, want %d", rec.Code, http.StatusTeapot)
	}
	if body := rec.Body.String(); body != "hi" {
		t.Errorf("body = %q, want %q", body, "hi")
	}
}
